-- Item Rare/Ex flags (migration 102), taken from LandSandBoat's `item_basic` table.
--
-- Retail marks an item Rare (0x08000) when a character may hold only one copy, and Ex
-- (0x04000) when it cannot be traded or sold.  Fanxi needs the Rare flag to keep Onedough and
-- Twodough (and any future character) from holding two copies of the same piece; the Ex flag
-- is recorded for completeness and for the item panels that want to show it.
--
-- Only the 798 items in the catalogue are flagged.  A later migration that adds an item
-- must set `rare` (and `ex`) on its row if the item has those retail flags.

ALTER TABLE items ADD COLUMN rare INTEGER NOT NULL DEFAULT 0;
ALTER TABLE items ADD COLUMN ex INTEGER NOT NULL DEFAULT 0;

-- Rare: one per character.
